def merge_intervals(intervals):
    """Merge overlapping closed intervals; return a sorted list of tuples."""
    out = []
    for s, e in sorted(intervals):
        if out and s <= out[-1][1]:
            out[-1] = (out[-1][0], e)
        else:
            out.append((s, e))
    return out

