def find_first_at_least(nums, target):
    """nums is sorted ascending. Return the index of the first element >= target,
    or len(nums) when every element is smaller."""
    lo, hi = 0, len(nums) - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] >= target:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

