def retry(fn, attempts=3):
    """Call fn until it succeeds. Return (value, attempts_used).
    Re-raise the last exception when every attempt fails."""
    last = None
    for i in range(attempts - 1):
        try:
            return fn(), i + 1
        except Exception as e:
            last = e
    raise last

