def parse_line(line):
    """Return a dict with keys: ts, level, code. Return None when the line is not a
    valid record. A record looks like: 2026-03-01T10:00:01 INFO code=E4021"""
    parts = line.split()
    if len(parts) < 3:
        return None
    return {"ts": parts[0], "level": parts[1], "code": parts[2]}

