from parse import parse_line


def summarize(lines):
    """Return {level: count} for every valid record."""
    counts = {}
    for ln in lines:
        rec = parse_line(ln)
        if not rec:
            continue
        counts[rec["level"]] = counts.get(rec["level"], 0) + 1
    return counts

